pub fn unsafe_get_heat_control() -> Option<Isolette_Data_Model::On_Off>
{
  unsafe {
    let value: *mut Isolette_Data_Model::On_Off = &mut Isolette_Data_Model::On_Off::default();
    if (get_heat_control(value)) {
      return Some(*value);
    } else {
      return None;
    }
  }
}

pub fn unsafe_get_heat_control_num_invalid() -> u64
{
  unsafe {
    return get_heat_control_num_invalid();
  }
}

pub fn unsafe_put_sv_heater_state(value: &Isolette_Data_Model::On_Off) -> bool
{
  unsafe {
    return put_sv_heater_state(value as *const Isolette_Data_Model::On_Off as *mut Isolette_Data_Model::On_Off);
  }
}

pub fn unsafe_is_injection_enabled() -> bool
{
  unsafe {
    return is_injection_enabled();
  }
}

pub fn unsafe_get_inj_sv_heater_state() -> Option<Isolette_Data_Model::On_Off>
{
  unsafe {
    let mut value: Isolette_Data_Model::On_Off = Isolette_Data_Model::On_Off::default();
    if get_inj_sv_heater_state(&mut value) {
      return Some(value);
    } else {
      return None;
    }
  }
}

pub fn unsafe_is_monitoring_enabled() -> bool
{
  unsafe {
    return is_monitoring_enabled();
  }
}

